import 'package:fancad_updater/fancad_updater.dart';

/// Pinned RSA public key for update manifests.
///
/// Generate the offline key once, then paste the modulus printed by:
///
/// ```bash
/// openssl rsa -in fancad-update.pem -noout -modulus
/// ```
///
/// An empty value disables downloads: FanCAD never installs bytes it cannot
/// verify against a signed manifest. The private key must never live in this
/// repository.
const String fanCadUpdateKeyModulus =
    '';

/// Null when the modulus is empty.
ManifestVerifier? createUpdateVerifier() {
  final modulus = fanCadUpdateKeyModulus.trim();
  if (modulus.isEmpty) return null;
  return ManifestVerifier(RsaPublicKey.fromHex(modulus: modulus));
}
